/**
 * Tests whether the option requires more arguments to be valid.
 *
 * @return false if the option doesn't require more arguments.
 */
boolean requiresArg() {
    if (optionalArg) {
        return false;
    }
    if (argCount == UNLIMITED_VALUES) {
        return values.isEmpty();
    }
    return acceptsArg();
}
